import type { ComponentPropsWithoutRef, MouseEvent } from 'react';
import { useTranslation } from 'react-i18next';
import type { Element } from 'hast';
import { t } from '@/lib/i18n';
import { openExternalUrl } from '../external';

type MarkdownLinkProps = ComponentPropsWithoutRef<'a'> & { node?: Element };

const BACKREF_LABEL = /^Back to reference ([\d-]+)$/i;

/**
 * Localizes the English `aria-label` generated by `remark-gfm` for backrefs.
 * The pattern keeps matching the English label the plugin emits; only the
 * displayed text is translated.
 */
function localizeBackrefLabel(label?: string): string {
  const match = label ? BACKREF_LABEL.exec(label.trim()) : null;
  return match
    ? t('chat:markdown.backrefWithId', { id: match[1] })
    : t('chat:markdown.backref');
}

/** Decodes a hash anchor without ever throwing on malformed escapes. */
function decodeAnchorId(rawId: string): string {
  try {
    return decodeURIComponent(rawId);
  } catch {
    return rawId;
  }
}

/**
 * Scrolls to an in-message anchor (`#user-content-fn-1`) without navigating the
 * window. Lookup is scoped to the `.zylara-prose` container so two messages
 * with footnotes do not fight over the same generated ids.
 */
function scrollToAnchor(href: string, current: HTMLAnchorElement): void {
  const id = decodeAnchorId(href.slice(1));
  if (!id) return;
  const scope: ParentNode = current.closest('.zylara-prose') ?? document;
  const target = Array.from(scope.querySelectorAll<HTMLElement>('[id]')).find((element) => element.id === id);
  if (!target) return;
  target.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

/**
 * Link renderer (docs §3/§4): external `http(s)` and `mailto:` links are handed
 * to the OS opener, internal `#anchors` scroll inside the message, footnote
 * refs/backrefs keep their generated attributes, and unsafe URLs never render
 * as a clickable link.
 */
export function MarkdownLink({
  node,
  href,
  title,
  children,
  className,
  onClick,
  'aria-label': ariaLabel,
  ...rest
}: MarkdownLinkProps) {
  useTranslation('chat');
  const rawHref = typeof href === 'string' ? href.trim() : '';
  const isAnchor = rawHref.startsWith('#');
  const isHttp = /^https?:\/\//i.test(rawHref);
  const isMailto = /^mailto:/i.test(rawHref);
  const isSafe = isAnchor || isHttp || isMailto;

  const isFootnoteRef = node?.properties?.dataFootnoteRef !== undefined;
  const isFootnoteBackref = node?.properties?.dataFootnoteBackref !== undefined;

  if (!isSafe) {
    // Unsafe/unknown URL: keep the text, drop the interaction entirely.
    return <span className={className}>{children}</span>;
  }

  const label = isFootnoteBackref ? localizeBackrefLabel(ariaLabel) : ariaLabel;

  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event);
    if (event.defaultPrevented) return;
    if (isAnchor) {
      event.preventDefault();
      scrollToAnchor(rawHref, event.currentTarget);
      return;
    }
    event.preventDefault();
    void openExternalUrl(rawHref);
  };

  return (
    <a
      {...rest}
      href={rawHref}
      title={title}
      className={className}
      aria-label={label}
      rel={isHttp ? 'noreferrer noopener' : undefined}
      data-footnote-ref={isFootnoteRef ? '' : undefined}
      data-footnote-backref={isFootnoteBackref ? '' : undefined}
      onClick={handleClick}
    >
      {children}
    </a>
  );
}
